function outlier_indices = detect_and_report_outliers(time, noise) 
if length(time) ~= length(noise) 
error('time 和noise 的长度必须相同'); 
end 
if ~isvector(time) || ~isvector(noise) 
error('time 和noise 必须是向量'); 
