% 转换为列向量 
time = time(:); 
noise = noise(:); 
total_samples = length(time); 
% 计算time 的四分位数和正常范围 
q1_time = quantile(time, 0.25); 
q3_time = quantile(time, 0.75); 
iqr_time = q3_time - q1_time; 
time_lower = q1_time - 1.5 * iqr_time; 
time_upper = q3_time + 1.5 * iqr_time; 
% 计算noise 的四分位数和正常范围 
