function result = delete_elements(original_array, dim, delete_indices)

47 
if dim < 1 || dim > ndims(original_array) 
error('指定的维度超出数组维度范围'); 
end 
% 将删除索引转换为行向量并去重、排序 
delete_indices = unique(sort(delete_indices(:).')); % 确保索引唯一且有序 
% 检查索引是否在有效范围内 
dim_size = size(original_array, dim); 
if any(delete_indices < 1) || any(delete_indices > dim_size) 
error('删除索引超出维度范围'); 
end 
% 计算需要保留的索引 
all_indices = 1:dim_size; 
keep_indices = setdiff(all_indices, delete_indices); 
% 构造索引单元格数组，用于访问数组 
indices = cell(1, ndims(original_array)); 
for i = 1:ndims(original_array) 
if i == dim 
indices{i} = keep_indices; % 在指定维度使用保留的索引 
else 
indices{i} = ':'; % 其他维度保留所有元素 
end 
end 
% 执行删除操作 
result = original_array(indices{:}); 
end 



