function [sinr_matrix, noise_power] = calculate_txbf_sinr_dbm(csi_tensor, 
noise_dBm) 
[num_h, num_carriers, num_samples] = size(csi_tensor); 
% 验证信道张量维度（必须为8×122×nsample，对应2Rx×4Tx） 
if num_h ~= 8 || num_carriers ~= 122 
error('信道张量维度错误！需为 8×122×nsample（8=2Rx×4Tx，122 子载波）'); 
end 
% 验证底噪向量长度（需与样本数一致） 
if length(noise_dBm) ~= num_samples 
error('底噪向量长度（%d）与样本数（%d）不匹配', length(noise_dBm), num_samples); 
end 

% 初始化输出 
sinr_matrix = zeros(num_carriers, num_samples); % 122×nsample SINR 矩阵 
noise_power = zeros(num_samples, 1); % 转换后的底噪（单位：W） 


for s = 1:num_samples 
dbm = noise_dBm(s); 
% 1. dBm → mW：P_mW = 10^(dBm/10) 
p_mw = 10^(dbm / 10); 
% 2. mW → W：1 W = 1000 mW 
p_w = p_mw / 1000; 
noise_power(s) = max(p_w, 1e-16); 


for sample_idx = 1:num_samples 
% 提取当前样本的所有子载波信道数据（8×122）

54 
csi_sample = csi_tensor(:, :, sample_idx); 
% 提取当前样本的线性底噪功率（W） 
current_noise = noise_power(sample_idx); 

% 遍历每个子载波（122 个） 
for carrier_idx = 1:num_carriers 
% 从8×1 向量中提取当前子载波的信道系数，重构为2Rx×4Tx 矩阵 
h_vec = csi_sample(:, carrier_idx); % 8 个信道系数（按Rx-Rx-Tx 顺序存储） 
H = reshape(h_vec, 2, 4); % 2×4 复信道矩阵：H(n,m) = 第m 根Tx 到第n 根Rx 的系数 

H_conjT = H'; % 共轭转置（复矩阵需用'，实矩阵等价于转置） 
norm_H = norm(H_conjT, 'fro'); % Frobenius 范数（矩阵元素平方和开根号） 
V = H_conjT / norm_H; % 4×2 权重矩阵（4Tx×2 流，流数=接收天线数） 

signal_power = norm(H * V, 'fro')^2; % ||H*V||_F²（Frobenius 范数平方） 
% 2. SINR（线性域转dB）：SINR_dB = 10*log10(信号功率/噪声功率) 
sinr_linear = signal_power / current_noise; 
sinr_matrix(carrier_idx, sample_idx) = 10 * log10(sinr_linear); 
end 

% 显示计算进度（每10 个样本打印一次） 
if mod(sample_idx, 10) == 0 
fprintf('已处理 %d/%d 个样本\n', sample_idx, num_samples); 
end 
end 

end 



