class ResidualBlock(nn.Module):  # (残差块不变) 
    # ... 
    def __init__(self, in_channels, out_channels, stride=1): 
        super(ResidualBlock, self).__init__(); 
        self.relu = nn.ReLU() 
        self.conv1 = nn.Conv2d(in_channels, out_channels, kernel_size=3, stride=stride, padding=1, 
bias=False); 
        self.bn1 = nn.BatchNorm2d(out_channels) 
        self.conv2 = nn.Conv2d(out_channels, out_channels, kernel_size=3, stride=1, padding=1, bias=False); 
        self.bn2 = nn.BatchNorm2d(out_channels) 
        self.downsample = nn.Sequential() 
        if stride != 1 or in_channels != out_channels: self.downsample = nn.Sequential( 
            nn.Conv2d(in_channels, out_channels, kernel_size=1, stride=stride, bias=False), 
            nn.BatchNorm2d(out_channels)) 

    def forward(self, x): 
        identity = self.downsample(x); 
        out = self.relu(self.bn1(self.conv1(x))); 
        out = self.bn2(self.conv2(out)); 
        out += identity; 
        out = self.relu(out) 
        return out 


class PhysicallyInformedClassifier(nn.Module): 
    def __init__(self, num_classes, dropout_rate=0.5): 
        super(PhysicallyInformedClassifier, self).__init__() 
        self.in_channels = 32 
        self.relu = nn.ReLU() 

        # --- 核心改动: 输入通道数从1 变为2 --- 
        self.freq_feature_extractor = nn.Sequential( 
            nn.Conv2d(2, 32, kernel_size=(1, 11), stride=1, padding=(0, 5), bias=False), 
            nn.BatchNorm2d(32), 
            nn.ReLU() 
        )

61 

        # ... (后续层定义不变) ... 
        self.layer1 = self._make_layer(ResidualBlock, 64, 2, stride=2) 
        self.layer2 = self._make_layer(ResidualBlock, 128, 2, stride=2) 
        self.avgpool = nn.AdaptiveAvgPool2d((1, 1)) 
        self.dropout = nn.Dropout(p=dropout_rate) 
        self.fc = nn.Linear(128, num_classes) 
        self._initialize_weights() 

    # ... (其他方法 _make_layer, forward, _initialize_weights 不变) ... 
    def _make_layer(self, block, out_channels, num_blocks, stride): 
        strides = [stride] + [1] * (num_blocks - 1); 
        layers = [] 
        for s in strides: layers.append(block(self.in_channels, out_channels, s)); self.in_channels = out_channels 
        return nn.Sequential(*layers) 

    def forward(self, x): 
        out = self.freq_feature_extractor(x); 
        self.in_channels = 32; 
        out = self.layer1(out); 
        out = self.layer2(out) 
        out = self.avgpool(out); 
        out = torch.flatten(out, 1); 
        out = self.dropout(out); 
        out = self.fc(out) 
        return out 

    def _initialize_weights(self): 
        for m in self.modules(): 
            if isinstance(m, nn.Conv2d): 
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu') 
            elif isinstance(m, nn.BatchNorm2d): 
                nn.init.constant_(m.weight, 1); nn.init.constant_(m.bias, 0) 
            elif isinstance(m, nn.Linear): 
                nn.init.xavier_normal_(m.weight) 
                if m.bias is not None: nn.init.constant_(m.bias, 0) 


